UPDATE about_us_sections SET content = 'Living With Arthritis was founded by First Contact Practitioners working within the NHS, with a shared aim of providing awareness and education about osteoarthritis-related problems to the patient population. Arthritis is the UK''s leading cause of pain and disability, affecting over 10 million people — yet it remains widely misunderstood. We believe every person living with joint pain deserves world-class support, clear information and a community that truly understands. Our story began with a simple question: why should expert arthritis care be limited by geography, income or waiting lists?', updated_at = now() WHERE id = '89d28532-6876-41de-8757-ad41b842dc6d';